/// Variants are identified by the `type` property.
#[derive(Debug, Clone, PartialEq)]
pub enum Normalizer {
    Lowercase(LowercaseNormalizer),
    Custom(CustomNormalizer),
}

impl serde::Serialize for Normalizer {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::Error;
        let (tag, value) = match self {
            Normalizer::Lowercase(value) => (
                serde_json::Value::from("lowercase"),
                serde_json::to_value(value),
            ),
            Normalizer::Custom(value) => (
                serde_json::Value::from("custom"),
                serde_json::to_value(value),
            ),
        };
        let mut object = serde_json::Map::new();
        object.insert("type".to_string(), tag);
        if let serde_json::Value::Object(fields) = value.map_err(S::Error::custom)? {
            object.extend(fields);
        }
        object.serialize(serializer)
    }
}

impl<'de> serde::Deserialize<'de> for Normalizer {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        use serde::de::Error;
        let mut object = serde_json::Map::deserialize(deserializer)?;
        let tag = object
            .remove("type")
            .unwrap_or_else(|| serde_json::Value::from("custom"));
        let result = match tag.as_str() {
            Some("lowercase") => serde_json::from_value(object.into()).map(Normalizer::Lowercase),
            Some("custom") => serde_json::from_value(object.into()).map(Normalizer::Custom),
            _ => return Err(D::Error::custom(format!("unknown Normalizer type {tag}"))),
        };
        result.map_err(D::Error::custom)
    }
}

impl From<LowercaseNormalizer> for Normalizer {
    fn from(value: LowercaseNormalizer) -> Self {
        Normalizer::Lowercase(value)
    }
}

impl From<CustomNormalizer> for Normalizer {
    fn from(value: CustomNormalizer) -> Self {
        Normalizer::Custom(value)
    }
}

impl From<LowercaseNormalizerBuilder> for Normalizer {
    fn from(builder: LowercaseNormalizerBuilder) -> Self {
        builder.build().into()
    }
}

impl From<CustomNormalizerBuilder> for Normalizer {
    fn from(builder: CustomNormalizerBuilder) -> Self {
        builder.build().into()
    }
}

impl Normalizer {
    /// Creates a builder for [`Normalizer`].
    ///
    /// Required: a variant.
    pub fn builder() -> NormalizerBuilder {
        NormalizerBuilder::new()
    }

    /// Creates a [`Normalizer`] from a function that sets the members of its builder.
    ///
    /// Required: a variant.
    pub fn of<B: crate::typed::builder::Build<Output = Normalizer>>(
        f: impl FnOnce(NormalizerBuilder) -> B,
    ) -> Normalizer {
        f(Self::builder()).build()
    }
}

