#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(untagged)]
pub enum Tokenizer {
    String(String),
    TokenizerDefinition(TokenizerDefinition),
}

impl From<String> for Tokenizer {
    fn from(value: String) -> Self {
        Tokenizer::String(value)
    }
}

impl From<TokenizerDefinition> for Tokenizer {
    fn from(value: TokenizerDefinition) -> Self {
        Tokenizer::TokenizerDefinition(value)
    }
}

impl From<&str> for Tokenizer {
    fn from(value: &str) -> Self {
        Tokenizer::String(value.into())
    }
}

#[derive(Debug, Clone, Default, PartialEq, serde::Serialize, serde::Deserialize)]
