pub enum TokenizerDefinition {
    CharGroup(CharGroupTokenizer),
    Classic(ClassicTokenizer),
    EdgeNgram(EdgeNGramTokenizer),
    Keyword(KeywordTokenizer),
    Letter(LetterTokenizer),
    Lowercase(LowercaseTokenizer),
    Ngram(NGramTokenizer),
    PathHierarchy(PathHierarchyTokenizer),
    Pattern(PatternTokenizer),
    SimplePattern(SimplePatternTokenizer),
    SimplePatternSplit(SimplePatternSplitTokenizer),
    Standard(StandardTokenizer),
    Thai(ThaiTokenizer),
    UaxUrlEmail(UaxEmailUrlTokenizer),
    Whitespace(WhitespaceTokenizer),
    IcuTokenizer(IcuTokenizer),
    KuromojiTokenizer(KuromojiTokenizer),
    NoriTokenizer(NoriTokenizer),
    /// A variant unknown to this client.
    Unknown(serde_json::Value),
}

impl serde::Serialize for TokenizerDefinition {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::Error;
        let (tag, value) = match self {
            TokenizerDefinition::CharGroup(value) => (
                serde_json::Value::from("char_group"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Classic(value) => (
                serde_json::Value::from("classic"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::EdgeNgram(value) => (
                serde_json::Value::from("edge_ngram"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Keyword(value) => (
                serde_json::Value::from("keyword"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Letter(value) => (
                serde_json::Value::from("letter"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Lowercase(value) => (
                serde_json::Value::from("lowercase"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Ngram(value) => (
                serde_json::Value::from("ngram"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::PathHierarchy(value) => (
                serde_json::Value::from("path_hierarchy"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Pattern(value) => (
                serde_json::Value::from("pattern"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::SimplePattern(value) => (
                serde_json::Value::from("simple_pattern"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::SimplePatternSplit(value) => (
                serde_json::Value::from("simple_pattern_split"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Standard(value) => (
                serde_json::Value::from("standard"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Thai(value) => {
                (serde_json::Value::from("thai"), serde_json::to_value(value))
            }
            TokenizerDefinition::UaxUrlEmail(value) => (
                serde_json::Value::from("uax_url_email"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Whitespace(value) => (
                serde_json::Value::from("whitespace"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::IcuTokenizer(value) => (
                serde_json::Value::from("icu_tokenizer"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::KuromojiTokenizer(value) => (
                serde_json::Value::from("kuromoji_tokenizer"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::NoriTokenizer(value) => (
                serde_json::Value::from("nori_tokenizer"),
                serde_json::to_value(value),
            ),
            TokenizerDefinition::Unknown(value) => return value.serialize(serializer),
        };
        let mut object = serde_json::Map::new();
        object.insert("type".to_string(), tag);
        if let serde_json::Value::Object(fields) = value.map_err(S::Error::custom)? {
            object.extend(fields);
        }
        object.serialize(serializer)
    }
}

impl<'de> serde::Deserialize<'de> for TokenizerDefinition {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        use serde::de::Error;
        let mut object = serde_json::Map::deserialize(deserializer)?;
        let tag = object
            .remove("type")
            .ok_or_else(|| D::Error::missing_field("type"))?;
        let result = match tag.as_str() {
            Some("char_group") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::CharGroup)
            }
            Some("classic") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::Classic)
            }
            Some("edge_ngram") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::EdgeNgram)
            }
            Some("keyword") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::Keyword)
            }
            Some("letter") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::Letter)
            }
            Some("lowercase") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::Lowercase)
            }
            Some("ngram") => serde_json::from_value(object.into()).map(TokenizerDefinition::Ngram),
            Some("path_hierarchy") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::PathHierarchy)
            }
            Some("pattern") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::Pattern)
            }
            Some("simple_pattern") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::SimplePattern)
            }
            Some("simple_pattern_split") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::SimplePatternSplit)
            }
            Some("standard") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::Standard)
            }
            Some("thai") => serde_json::from_value(object.into()).map(TokenizerDefinition::Thai),
            Some("uax_url_email") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::UaxUrlEmail)
            }
            Some("whitespace") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::Whitespace)
            }
            Some("icu_tokenizer") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::IcuTokenizer)
            }
            Some("kuromoji_tokenizer") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::KuromojiTokenizer)
            }
            Some("nori_tokenizer") => {
                serde_json::from_value(object.into()).map(TokenizerDefinition::NoriTokenizer)
            }
            _ => {
                object.insert("type".to_string(), tag);
                return Ok(TokenizerDefinition::Unknown(object.into()));
            }
        };
        result.map_err(D::Error::custom)
    }
}

